const form = document.querySelector("#progressForm");
const courseNameInput = document.querySelector("#courseName");
const completedLessonsInput =
    document.querySelector("#completedLessons");
const progressStatus =
    document.querySelector("#progressStatus");

const STORAGE_KEY = "courseProgress";

function renderProgress(data) {
    progressStatus.textContent =
        `${data.courseName}: ${data.completedLessons} lessons completed`;
}

form.addEventListener("submit", (event) => {
    event.preventDefault();

    const courseName = courseNameInput.value.trim();
    const completedLessons =
        Number(completedLessonsInput.value);

    if (!courseName) {
        progressStatus.textContent =
            "Please enter a course name.";
        return;
    }

    if (
        Number.isNaN(completedLessons) ||
        completedLessons < 0
    ) {
        progressStatus.textContent =
            "Enter a valid completed lesson count.";
        return;
    }

    const progress = {
        courseName,
        completedLessons
    };

    localStorage.setItem(
        STORAGE_KEY,
        JSON.stringify(progress)
    );

    renderProgress(progress);
});

const savedProgress =
    localStorage.getItem(STORAGE_KEY);

if (savedProgress) {
    const progress = JSON.parse(savedProgress);
    renderProgress(progress);
}

