// courseIdGenerator.js
export function* courseIdGenerator(year) {
    let number = 1;

    while (true) {
        const id = `JS-${year}-${String(number).padStart(3, "0")}`;
        yield id;
        number++;
    }
}


// main.js
import { courseIdGenerator } from "./courseIdGenerator.js";

const students = [
    {
        name: "Rahul",
        enrollmentDate: new Date("2026-08-10")
    },
    {
        name: "Priya",
        enrollmentDate: new Date("2026-08-12")
    },
    {
        name: "Amit",
        enrollmentDate: new Date("2026-08-15")
    }
];

const idPattern = /^JS-\d{4}-\d{3}$/;
const generator = courseIdGenerator(2026);

const enrollments = students.map((student) => {
    const courseId = generator.next().value;
    const valid = idPattern.test(courseId);

    return {
        courseId,
        student,
        valid
    };
});

const dateFormatter = new Intl.DateTimeFormat("en-IN", {
