async function loadCourseDashboard() {
    try {
        const [courseResponse, lessonsResponse] = await Promise.all([
            fetch("/api/course"),
            fetch("/api/lessons")
        ]);

        if (!courseResponse.ok) {
            throw new Error("Failed to load course data.");
        }

        if (!lessonsResponse.ok) {
            throw new Error("Failed to load lesson data.");
        }

        const [course, lessons] = await Promise.all([
            courseResponse.json(),
            lessonsResponse.json()
        ]);

        console.log("Course Dashboard Loaded");
        console.log("Course:", course);
        console.log("Lessons:", lessons);
    } catch (error) {
        console.error("Unable to load course dashboard:", error.message);
    }
}

loadCourseDashboard();

function createCourseDashboardLoader() {
    const controller = new AbortController();

    async function load() {
        try {
            const [courseResponse, lessonsResponse] = await Promise.all([
                fetch("/api/course", {
                    signal: controller.signal
                }),
                fetch("/api/lessons", {
                    signal: controller.signal
                })
            ]);

            if (!courseResponse.ok) {
                throw new Error("Failed to load course data.");
            }

            if (!lessonsResponse.ok) {
                throw new Error("Failed to load lesson data.");
            }

            const [course, lessons] = await Promise.all([
                courseResponse.json(),
                lessonsResponse.json()
            ]);

            console.log("Course Dashboard Loaded");
            console.log("Course:", course);
            console.log("Lessons:", lessons);
        } catch (error) {
            if (error.name === "AbortError") {
                console.log("Course loading cancelled.");
                return;
            }

            console.error(
                "Course dashboard failed:",
                error.message
            );
        }
    }

    function cancel() {
        controller.abort();
    }

    return {
        load,
        cancel
    };
}

const dashboardLoader = createCourseDashboardLoader();

dashboardLoader.load();

